-- Privacy decisions are explicit. No clock-driven destruction or release.
CREATE TABLE env_privacy_holds (
 company_id TEXT NOT NULL REFERENCES env_companies(id), record_id TEXT NOT NULL,
 fingerprint TEXT NOT NULL, legal_basis TEXT NOT NULL, custodian TEXT NOT NULL,
 release_at TEXT NOT NULL, released_at INTEGER, release_reason TEXT,
 PRIMARY KEY(company_id,record_id)
);
CREATE TABLE env_privacy_epochs (company_id TEXT PRIMARY KEY REFERENCES env_companies(id), version INTEGER NOT NULL);
CREATE TABLE env_privacy_guard (company_id TEXT NOT NULL, table_name TEXT NOT NULL, PRIMARY KEY(company_id,table_name));
CREATE TABLE env_privacy_redactions (company_id TEXT NOT NULL,target_id TEXT NOT NULL,replacement TEXT NOT NULL,PRIMARY KEY(company_id,target_id));
CREATE TABLE env_privacy_source_fences (company_id TEXT NOT NULL REFERENCES env_companies(id),source_hash TEXT NOT NULL,PRIMARY KEY(company_id,source_hash));
DROP TRIGGER env_no_audit_update;
CREATE TRIGGER env_no_audit_update BEFORE UPDATE ON env_audit
WHEN NOT (NEW.id=OLD.id AND NEW.company_id=OLD.company_id AND NEW.actor_id=OLD.actor_id AND NEW.action=OLD.action
 AND NEW.version=OLD.version AND NEW.occurred_at=OLD.occurred_at AND EXISTS(SELECT 1 FROM env_privacy_redactions r
 WHERE r.company_id=OLD.company_id AND r.target_id=OLD.target_id AND r.replacement=NEW.target_id))
BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;
DROP TRIGGER env_workspace_immutable_delete;
CREATE TRIGGER env_workspace_immutable_delete BEFORE DELETE ON env_workspace_versions WHEN NOT EXISTS(SELECT 1 FROM env_privacy_guard WHERE company_id=OLD.company_id AND table_name='env_workspace_versions') BEGIN SELECT RAISE(ABORT,'immutable_payroll_input'); END;
DROP TRIGGER env_workspace_decision_delete;
CREATE TRIGGER env_workspace_decision_delete BEFORE DELETE ON env_workspace_decisions WHEN NOT EXISTS(SELECT 1 FROM env_privacy_guard WHERE company_id=OLD.company_id AND table_name='env_workspace_decisions') BEGIN SELECT RAISE(ABORT,'immutable_payroll_decision'); END;
