CREATE TRIGGER env_locations_privacy_insert AFTER INSERT ON env_locations BEGIN INSERT INTO env_privacy_epochs(company_id,version) VALUES(NEW.company_id,1) ON CONFLICT(company_id) DO UPDATE SET version=version+1; END;
